import org.jetbrains.kotlin.gradle.dsl.JvmTarget

// The tunnel URL is generated by start-ngrok.ps1. Accept an explicit override so a
// physical device can reach the same Ktor instance as the web app.
val tunnelUrlFile = rootProject.layout.projectDirectory.file("web/ngrok-url.txt")
val tunnelBackendUrl = providers.fileContents(tunnelUrlFile).asText
    .orElse("")
    .map { value -> value.trim().trimEnd('/').ifBlank { "http://10.0.2.2:8080" } }
val civicBackendUrl = providers.gradleProperty("THEEKHAI_BACKEND_URL")
    .orElse(providers.environmentVariable("THEEKHAI_BACKEND_URL"))
    .orElse(tunnelBackendUrl)
    .get()

plugins {
    alias(libs.plugins.androidApplication)
    alias(libs.plugins.composeCompiler)
}

kotlin {
    compilerOptions {
        jvmTarget = JvmTarget.JVM_11
    }
}
dependencies {
    implementation(project(":app:shared"))
    implementation(project(":core"))
    implementation(project(":domain"))

    implementation(libs.androidx.activity.compose)
    implementation(libs.koin.android)

    implementation(libs.compose.material3)
    implementation(libs.compose.uiToolingPreview)
    debugImplementation(libs.compose.uiTooling)
}

android {
    namespace = "com.example.theekhai"
    compileSdk = libs.versions.android.compileSdk.get().toInt()

    defaultConfig {
        applicationId = "com.example.theekhai"
        minSdk = libs.versions.android.minSdk.get().toInt()
        targetSdk = libs.versions.android.targetSdk.get().toInt()
        versionCode = 1
        versionName = "1.0"
        manifestPlaceholders["allowCleartext"] = "false"
        manifestPlaceholders["theekhaiBackendUrl"] = civicBackendUrl
    }
    packaging {
        resources {
            excludes += "/META-INF/{AL2.0,LGPL2.1}"
        }
    }
    buildTypes {
        debug {
            // The emulator uses the local Ktor server at http://10.0.2.2:8080.
            manifestPlaceholders["allowCleartext"] = "true"
        }
        release {
            manifestPlaceholders["allowCleartext"] = "false"
            isMinifyEnabled = false
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro"
            )
        }
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_11
        targetCompatibility = JavaVersion.VERSION_11
    }
    buildFeatures {
        compose = true
    }
}
